    def _record_step15_alpha_gate(self, asset: str, passed: bool) -> None:
        stats = getattr(self, "_step15_alpha_gate_stats", None)
        if not isinstance(stats, dict):
            return
        stats["total"] = int(stats.get("total", 0) or 0) + 1
        if passed:
            stats["passed"] = int(stats.get("passed", 0) or 0) + 1
        by_asset = stats.setdefault("by_asset", {})
        asset_stats = by_asset.setdefault(asset, {"total": 0, "passed": 0})
        asset_stats["total"] = int(asset_stats.get("total", 0) or 0) + 1
        if passed:
            asset_stats["passed"] = int(asset_stats.get("passed", 0) or 0) + 1

    def _record_step15_ood_event(
        self,
        asset: str,
        shadow_only: bool,
        is_ood: bool,
        hard_switch: bool,
    ) -> None:
        stats = getattr(self, "_step15_ood_stats", None)
        if not isinstance(stats, dict):
            return
        stats["decisions"] = int(stats.get("decisions", 0) or 0) + 1
        by_asset = stats.setdefault("by_asset", {})
        asset_stats = by_asset.setdefault(
            asset,
            {
                "decisions": 0,
                "soft_degrade": 0,
                "hard_switch": 0,
                "shadow_alert": 0,
            },
        )
        asset_stats["decisions"] = int(asset_stats.get("decisions", 0) or 0) + 1

        if shadow_only:
            if is_ood:
                stats["shadow_alert"] = int(stats.get("shadow_alert", 0) or 0) + 1
                asset_stats["shadow_alert"] = int(asset_stats.get("shadow_alert", 0) or 0) + 1
            return

        if hard_switch:
            stats["hard_switch"] = int(stats.get("hard_switch", 0) or 0) + 1
            asset_stats["hard_switch"] = int(asset_stats.get("hard_switch", 0) or 0) + 1
        elif is_ood:
            stats["soft_degrade"] = int(stats.get("soft_degrade", 0) or 0) + 1
            asset_stats["soft_degrade"] = int(asset_stats.get("soft_degrade", 0) or 0) + 1

    @staticmethod
    def _new_realized_pnl_bucket() -> Dict[str, Any]:
        return {
            "count": 0,
            "wins": 0,
            "losses": 0,
            "breakeven": 0,
            "win_rate": None,
            "total_pnl_usd": 0.0,
            "total_pnl_bps": 0.0,
            "avg_pnl_usd": None,
            "avg_pnl_bps": None,
            "last_pnl_usd": 0.0,
            "last_pnl_bps": 0.0,
            "last_asset": "",
            "last_strategy": "",
            "last_exit_type": "",
            "last_updated_at": None,
        }

    def _new_realized_pnl_breakdown(self) -> Dict[str, Any]:
        return {
            "closed_trade_count": 0,
            "total": self._new_realized_pnl_bucket(),
            "by_side": {},
            "by_asset": {},
            "by_strategy": {},
            "by_asset_side": {},
            "by_side_strategy": {},
        }

    def _ensure_realized_pnl_breakdown(self) -> Dict[str, Any]:
        breakdown = getattr(self, "_realized_pnl_breakdown", None)
        if not isinstance(breakdown, dict):
            breakdown = self._new_realized_pnl_breakdown()
            self._realized_pnl_breakdown = breakdown
            return breakdown

        breakdown.setdefault("closed_trade_count", 0)
        breakdown.setdefault("total", self._new_realized_pnl_bucket())
        for key in ("by_side", "by_asset", "by_strategy", "by_asset_side", "by_side_strategy"):
            if not isinstance(breakdown.get(key), dict):
                breakdown[key] = {}
        return breakdown

    def _update_realized_pnl_bucket(
        self,
        bucket: Dict[str, Any],
        *,
        pnl_usd: float,
        pnl_bps: float,
        asset: str,
        strategy: str,
        exit_type: str,
        updated_at: str,
    ) -> None:
        count = int(bucket.get("count", 0) or 0) + 1
        wins = int(bucket.get("wins", 0) or 0)
        losses = int(bucket.get("losses", 0) or 0)
        breakeven = int(bucket.get("breakeven", 0) or 0)
        if pnl_usd > 0:
            wins += 1
        elif pnl_usd < 0:
            losses += 1
        else:
            breakeven += 1

        total_pnl_usd = float(bucket.get("total_pnl_usd", 0.0) or 0.0) + float(pnl_usd)
        total_pnl_bps = float(bucket.get("total_pnl_bps", 0.0) or 0.0) + float(pnl_bps)
        bucket.update(
            {
                "count": count,
                "wins": wins,
                "losses": losses,
                "breakeven": breakeven,
                "win_rate": (wins / count) if count > 0 else None,
                "total_pnl_usd": total_pnl_usd,
                "total_pnl_bps": total_pnl_bps,
                "avg_pnl_usd": (total_pnl_usd / count) if count > 0 else None,
                "avg_pnl_bps": (total_pnl_bps / count) if count > 0 else None,
                "last_pnl_usd": float(pnl_usd),
                "last_pnl_bps": float(pnl_bps),
                "last_asset": str(asset or ""),
                "last_strategy": str(strategy or ""),
                "last_exit_type": str(exit_type or ""),
                "last_updated_at": updated_at,
            }
        )

    def _record_realized_pnl_breakdown(
        self,
        *,
        asset: str,
        side: str,
        strategy: str,
        pnl_usd: float,
        pnl_bps: float,
        exit_type: str,
    ) -> None:
        breakdown = self._ensure_realized_pnl_breakdown()
        asset_key = str(asset or "").upper()
        side_key = str(side or "unknown").lower()
        strategy_key = str(strategy or "unknown")
        updated_at = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")

        buckets = [
            breakdown.setdefault("total", self._new_realized_pnl_bucket()),
            breakdown["by_side"].setdefault(side_key, self._new_realized_pnl_bucket()),
            breakdown["by_asset"].setdefault(asset_key, self._new_realized_pnl_bucket()),
            breakdown["by_strategy"].setdefault(strategy_key, self._new_realized_pnl_bucket()),
            breakdown["by_asset_side"].setdefault(
                f"{asset_key}:{side_key}", self._new_realized_pnl_bucket()
            ),
            breakdown["by_side_strategy"].setdefault(
                f"{side_key}:{strategy_key}", self._new_realized_pnl_bucket()
            ),
        ]

        for bucket in buckets:
            self._update_realized_pnl_bucket(
                bucket,
                pnl_usd=pnl_usd,
                pnl_bps=pnl_bps,
                asset=asset_key,
                strategy=strategy_key,
                exit_type=exit_type,
                updated_at=updated_at,
            )

        breakdown["closed_trade_count"] = int(
            breakdown.get("closed_trade_count", 0) or 0
        ) + 1

    def _get_realized_pnl_summary(self) -> Dict[str, Any]:
        breakdown = self._ensure_realized_pnl_breakdown()

        def _copy_buckets(raw: Dict[str, Any]) -> Dict[str, Any]:
            return {
                str(key): dict(value)
                for key, value in (raw or {}).items()
                if isinstance(value, dict)
            }

        return {
            "closed_trade_count": int(breakdown.get("closed_trade_count", 0) or 0),
            "tracked_sides": sorted(
                key
                for key, value in (breakdown.get("by_side", {}) or {}).items()
                if int((value or {}).get("count", 0) or 0) > 0
            ),
            "total": dict(breakdown.get("total", self._new_realized_pnl_bucket()) or {}),
            "by_side": _copy_buckets(breakdown.get("by_side", {})),
            "by_asset": _copy_buckets(breakdown.get("by_asset", {})),
            "by_strategy": _copy_buckets(breakdown.get("by_strategy", {})),
            "by_asset_side": _copy_buckets(breakdown.get("by_asset_side", {})),
            "by_side_strategy": _copy_buckets(breakdown.get("by_side_strategy", {})),
        }

