    def _get_quiet_accum_direction_floor(self, asset: str) -> float:
        base_floor = float(getattr(self, "_quiet_accum_min_direction", 0.0) or 0.0)
        by_asset = getattr(self, "_quiet_accum_min_direction_by_asset", None)
        if not isinstance(by_asset, dict):
            return base_floor
        override = by_asset.get(str(asset or "").upper())
        if override is None:
            return base_floor
        try:
            return max(0.0, float(override or 0.0))
        except Exception:
            return base_floor

